const oakBarriers = getCircleOrientations();

export const oakRoom: Sequence<NpcSequence> = (world, entity, state) => {
  const stage: QuestStage<NpcSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };

  const size = world.metadata.gameEntity[LEVEL].size;
  const roomEntity = assertIdentifierAndComponents(world, "oakRoom", [
    LIGHT,
    VIEWABLE,
  ]);
  const oakBoss = getIdentifierAndComponents(world, "oak_boss", [
    BELONGABLE,
    POSITION,
  ]);
  const heroEntity = getIdentifierAndComponents(world, "hero", [
    LIGHT,
    POSITION,
    EQUIPPABLE,
    STATS,
    SPAWNABLE,
    INVENTORY,
  ]);

  if (!heroEntity) {
    return { finished: stage.finished, updated: stage.updated };
  }

  const inRoom =
    !isDead(world, heroEntity) &&
    getDistance(entity[POSITION], heroEntity[POSITION], size) < 5.43;

  step({
    stage,
    name: START_STEP,
    isCompleted: () => true,
    onLeave: () => "wait",
  });

  step({
    stage,
    name: "wait",
    isCompleted: () => inRoom,
    onLeave: () => "enter",
  });

  step({
    stage,
    name: "defeat",
    forceEnter: () =>
      state.args.step === "fight" && (!oakBoss || isDead(world, heroEntity)),
    isCompleted: () => true,
    onLeave: () => {
      // remove barrier
      world
        .getEntities([IDENTIFIABLE])
        .filter((entity) => entity[IDENTIFIABLE].name === "oak:barrier")
        .forEach((entity) => {
          disposeEntity(world, entity);
        });

      return "enter";
    },
  });

  step({
    stage,
    name: "leave",
    forceEnter: () => state.args.step !== "wait" && !inRoom,
    isCompleted: () => true,
    onLeave: () => {
      heroEntity[LIGHT].brightness = heroEntity[LIGHT].visibility;
      rerenderEntity(world, heroEntity);

      roomEntity[LIGHT].brightness = 0;
      roomEntity[LIGHT].visibility = 0;
      roomEntity[VIEWABLE].active = false;
      rerenderEntity(world, roomEntity);

      return "wait";
    },
  });

  step({
    stage,
    name: "enter",
    onEnter: () => {
      heroEntity[LIGHT].brightness = 0;
      rerenderEntity(world, heroEntity);

      roomEntity[LIGHT].brightness = 7.2;
      roomEntity[LIGHT].visibility = 7;
      roomEntity[VIEWABLE].active = true;
      rerenderEntity(world, roomEntity);

      return true;
    },
    isCompleted: () =>
      !isDead(world, heroEntity) && oakBoss?.[BELONGABLE].faction === "wild",
    onLeave: () => "fight",
  });

  step({
    stage,
    name: "fight",
    onEnter: () => {
      for (const oakBarrier of oakBarriers) {
        const target = combine(size, oakBarrier);
        const barrierEntity = entities.createBarrier(world, {
          [BLOCKABLE]: {},
          [COLLIDABLE]: {},
          [FOG]: { visibility: "visible", type: "float", fixed: true },
          [ORIENTABLE]: { facing: oakBarrier.orientation },
          [POSITION]: target,
          [SPRITE]: oakBarrier.corner ? barrierCorner : barrierSide,
          [RENDERABLE]: { generation: 0 },
        });
        setIdentifier(world, barrierEntity, "oak:barrier");
      }
      return true;
    },
  });

  return { updated: stage.updated, finished: stage.finished };
};

export const chestNpc: Sequence<NpcSequence> = (world, entity, state) => {
  const stage: QuestStage<NpcSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };

  const heroEntity = getIdentifierAndComponents(world, "hero", [
    POSITION,
    EQUIPPABLE,
    STATS,
    SPAWNABLE,
    INVENTORY,
  ]);

  if (!heroEntity) {
    return { finished: stage.finished, updated: stage.updated };
  }

  // remember initial chest and tower positions
  if (!state.args.memory.initialPosition) {
    state.args.memory.initialPosition = copy(entity[POSITION]);
  }
  if (!state.args.memory.towerPositions) {
    state.args.memory.towerPositions = world
      .getEntities([IDENTIFIABLE, SPRITE, POSITION, BEHAVIOUR, STATS])
      .filter((tower) => tower[IDENTIFIABLE].name === "chest_tower_statue")
      .map((tower) => copy(tower[POSITION]));
  }

  step({
    stage,
    name: START_STEP,
    onEnter: () => true,
    isCompleted: () => entity[STATS].hp < entity[STATS].maxHp,
    onLeave: () => "awaken",
  });

  step({
    stage,
    name: "awaken",
    onEnter: () => {
      state.args.memory.awakened = state.elapsed;
      entity[BEHAVIOUR].patterns = [
        { name: "invincible", memory: {} },
        {
          name: "dialog",
          memory: {
            enemy: true,
            override: "visible",
            dialogs: [
              createShout(
                `${choice(
                  "Ouch",
                  "That hurt",
                  "My eyes",
                  "Don't touch me",
                  "Rude",
                  "How dare you"
                )}\u0112`
              ),
            ],
          },
        },
        {
          name: "chest_boss",
          memory: {
            phase: 1,
            position: state.args.memory.initialPosition,
          },
        },
        {
          name: "wait",
          memory: { ticks: 6 },
        },
        {
          name: "dialog",
          memory: {
            dialogs: [
              createShout(
                choice(
                  "Bad idea",
                  "Big mistake",
                  "Trouble ahead",
                  "Try harder",
                  "You will pay",
                  "That's your end",
                  "Prepare to die"
                )
              ),
            ],
          },
        },
        {
          name: "wait",
          memory: { ticks: 6 },
        },
        {
          name: "dialog",
          memory: {
            override: undefined,
            dialogs: [],
          },
        },
        {
          name: "wait",
          memory: { ticks: 3 },
        },
        { name: "vulnerable", memory: {} },
        {
          name: "chest_boss",
          memory: {
            phase: 2,
            position: state.args.memory.initialPosition,
          },
        },
      ];
      return true;
    },
    isCompleted: () => isDead(world, heroEntity),
    onLeave: () => "reset",
  });

  // reset boss after hero death
  step({
    stage,
    name: "reset",
    isCompleted: () => !isDead(world, heroEntity),
    onEnter: () => {
      // restore boss to normal state
      entity[STATS].hp = entity[STATS].maxHp;
      entity[SPRITE] = woodChest;
      entity[BELONGABLE].faction = "unit";
      entity[BEHAVIOUR].patterns = [
        { name: "vulnerable", memory: {} },
        {
          name: "dialog",
          memory: {
            idle: undefined,
            dialogs: [],
            override: undefined,
            enemy: undefined,
          },
        },
        {
          name: "move",
          memory: {
            targetPosition: state.args.memory.initialPosition,
          },
        },
      ];

      // restore statues
      state.args.memory.towerPositions.forEach((position: Position) => {
        getCellEntities(world, position).forEach((entity) =>
          disposeEntity(world, entity)
        );

        createCell(world, position, "chest_tower_statue", "hidden");
      });

      // remove any pending mobs or drops
      world
        .getEntities([IDENTIFIABLE])
        .filter(
          (drop) =>
            drop[IDENTIFIABLE].name === "chest_mob:drop" ||
            drop[IDENTIFIABLE].name === "chest_mob"
        )
        .forEach((entity) => {
          disposeEntity(
            world,
            entity[ITEM] ? world.assertById(entity[ITEM].carrier) : entity
          );
        });

      return true;
    },
    onLeave: () => START_STEP,
  });

  return { finished: stage.finished, updated: stage.updated };
};

export const oscillatingStormNpc: Sequence<NpcSequence> = (
  world,
  entity,
  state
) => {
  const stage: QuestStage<NpcSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };

  const { center, degrees, amplitude, frequency, ratio } = state.args.memory;
  const weatherSequence = getSequence(world, entity, "weather");

  if (!weatherSequence) {
    return { finished: stage.finished, updated: stage.updated };
  }

  if (!weatherSequence.args.end) {
    weatherSequence.args.end = Infinity;
  }

  const tick = world.metadata.gameEntity[REFERENCE].tick;
  const time = (state.elapsed / tick) * frequency;
  const oscillation = Math.sin(time) * amplitude;
  const radians = (degrees * Math.PI) / 180;
  const direction = {
    x: Math.cos(radians),
    y: Math.sin(radians),
  };
  const offset = {
    x: Math.round(direction.x * oscillation * ratio),
    y: Math.round(direction.y * oscillation),
  };
  const position = add(center, offset);

  if (
    weatherSequence.args.position.x !== position.x ||
    weatherSequence.args.position.y !== position.y
  ) {
    weatherSequence.args.position = position;
  }

  return { finished: stage.finished, updated: stage.updated };
};

export const wanderingTornadoNpc: Sequence<NpcSequence> = (
  world,
  entity,
  state
) => {
  const stage: QuestStage<NpcSequence> = {
    world,
    entity,
    state,
    finished: false,
    updated: false,
  };

  const {
    maximum,
    lastMove,
    lastGrow,
    orientation,
    biome,
    center,
    angle,
    radius,
    ratio,
  } = state.args.memory;
  const tornadoSequence = getSequence(world, entity, "tornado");

  if (!tornadoSequence) {
    return { finished: stage.finished, updated: stage.updated };
  }

  const generation = world.metadata.gameEntity[RENDERABLE].generation;
  const size = world.metadata.gameEntity[LEVEL].size;
  const moveTicks = generation - lastMove;
  const growTicks = generation - lastGrow;

  // move or shrink tornado
  if (moveTicks >= 3 && tornadoSequence.args.radius > 0 && orientation) {
    const delta = orientationPoints[orientation as Orientation];
    const target = combine(size, entity[POSITION], delta);
    if (isFlyable(world, target) && getBiome(world, target) === biome) {
      moveEntity(world, entity, target);
      state.args.memory.growing = true;
    } else if (tornadoSequence.args.radius > 0) {
      state.args.memory.growing = false;
      tornadoSequence.args.radius -= 1;
    }
    state.args.memory.lastMove = generation;
  }

  // grow tornado
  if (
    state.args.memory.growing &&
    growTicks >= 11 &&
    tornadoSequence.args.radius < maximum
  ) {
    tornadoSequence.args.radius += 1;
    state.args.memory.lastGrow = generation;
    state.args.memory.lastMove = generation;
  }

  // reposition tornado
  if (
    !state.args.memory.growing &&
    tornadoSequence.args.radius === 0 &&
    moveTicks >= 11
  ) {
    const spawnPoint = angledOffset(
      size,
      center,
      angle + random(-90, 90),
      random(10, Math.ceil(radius)),
      ratio
    );

    state.args.memory.growing = true;
    state.args.memory.orientation = relativeOrientations(
      world,
      spawnPoint,
      entity[POSITION]
    )[0];
    moveEntity(world, entity, spawnPoint);
  }

  return { finished: stage.finished, updated: stage.updated };
};
