export const isGhost = (world: World, entity: Entity) => entity[PLAYER]?.ghost;

export const isRespawning = (world: World, entity: Entity) =>
  isGhost(world, entity) && entity[MOVABLE]?.flying;

export const isSoulReady = (world: World, entity: Entity) =>
  isGhost(world, entity) && entity[SOUL]?.ready;

export const isRevivable = (world: World, entity: Entity) =>
  entity[REVIVABLE]?.available;

export const getRevivable = (world: World, position: Position) =>
  getCellEntities(world, position).find((target) =>
    isRevivable(world, target)
  ) as Entity | undefined;

export const canRevive = (world: World, entity: Entity, target: Entity) =>
  isRevivable(world, entity) && isGhost(world, target) && SOUL in target;

export const reviveEntity = (world: World, entity: Entity, target: Entity) => {
  entity[REVIVABLE].available = false;
  entity[TOOLTIP].dialogs = [];
  entity[TOOLTIP].changed = true;
  entity[TOOLTIP].override = undefined;

  // trigger vision and respawn on halo
  createSequence<"vision", VisionSequence>(
    world,
    target,
    "vision",
    "changeRadius",
    { fast: true }
  );
  createSequence<"revive", ReviveSequence>(
    world,
    target,
    "revive",
    "soulRespawn",
    {
      tombstoneId: world.getEntityId(entity),
      target: target[SPAWNABLE].position,
      viewable: target[SPAWNABLE].viewable,
      light: target[SPAWNABLE].light,
      compassId: target[SPAWNABLE].compassId,
    }
  );
};

export const createHero = (world: World, halo: Entity) => {
  const { stats, sprite, swimming } = getClassData(
    halo[SPAWNABLE].classKey,
    halo[SPAWNABLE].hairColor
  );

  const frameId = world.getEntityId(
    entities.createFrame(world, {
      [REFERENCE]: {
        tick: getHasteInterval(world, stats.haste),
        delta: 0,
        suspended: true,
        suspensionCounter: -1,
      },
      [RENDERABLE]: { generation: 0 },
    })
  );
  const heroEntity = entities.createHero(world, {
    [ACTIONABLE]: {
      spellTriggered: false,
      skillTriggered: false,
      interactTriggered: false,
      toolEquipped: false,
    },
    [AFFECTABLE]: getEmptyAffectable(),
    [ATTACKABLE]: { scratchColor: colors.silver },
    [BELONGABLE]: { faction: halo[BELONGABLE].faction },
    [BUMPABLE]: { generation: 0 },
    [COLLECTABLE]: {},
    [CONDITIONABLE]: {},
    [DROPPABLE]: { decayed: false },
    [EQUIPPABLE]: {},
    [FOG]: { visibility: "visible", type: "unit" },
    [INVENTORY]: { items: [] },
    [LAYER]: {},
    [LIGHT]: { visibility: 1, brightness: 1, darkness: 0 },
    [MELEE]: { hits: 0 },
    [MOVABLE]: {
      orientations: [],
      reference: frameId,
      spring: {
        mass: 0.1,
        friction: 50,
        tension: 1000,
      },
      lastInteraction: 0,
      flying: false,
      swimming: false,
    },
    [ORIENTABLE]: {},
    [PLAYER]: {
      ghost: false,
      receivedStats: { ...emptyReceivedStats },
      defeatedUnits: halo[PLAYER]?.defeatedUnits || {},
      quickItems: halo[PLAYER]?.quickItems || {},
      chatHistory: halo[PLAYER]?.chatHistory || [],
    },
    [POSITION]: copy(halo[POSITION]),
    [PUSHABLE]: {},
    [RENDERABLE]: { generation: 0 },
    [SEQUENCABLE]: { states: {} },
    [SHOOTABLE]: { shots: 0 },
    [SPAWNABLE]: {
      classKey: halo[SPAWNABLE].classKey,
      hairColor: halo[SPAWNABLE].hairColor,
      position: copy(halo[SPAWNABLE].position),
      light: halo[SPAWNABLE].light,
      viewable: halo[SPAWNABLE].viewable,
      quest: halo[SPAWNABLE].quest,
    },
    [SPRITE]: sprite,
    [STATS]: {
      hp: halo[SOUL]?.stats.maxHp || stats.maxHp,
      mp: 0,
      xp: 0,
      ...stats,
      ...halo[SOUL]?.stats,
    },
    [SWIMMABLE]: { swimming: false, sprite: swimming },
    [TOOLTIP]: { dialogs: [], persistent: false, nextDialog: -1 },
    [VIEWABLE]: halo[SPAWNABLE].viewable,
  });
  setIdentifier(world, heroEntity, "hero");

  createSequence<"vision", VisionSequence>(
    world,
    heroEntity,
    "vision",
    "changeRadius",
    { light: halo[SPAWNABLE].light, fast: false }
  );
  createSequence<"pointer", PointerSequence>(
    world,
    heroEntity,
    "pointer",
    "pointerArrow",
    {}
  );

  return heroEntity;
};

export default function setupFate(world: World) {
  let referencesGeneration = -1;

  const onUpdate = (delta: number) => {
    const generation = world
      .getEntities([RENDERABLE, REFERENCE])
      .reduce((total, entity) => entity[RENDERABLE].generation + total, 0);

    if (referencesGeneration === generation) return;

    referencesGeneration = generation;

    // initiate respawn sequence before decaying
    for (const entity of world.getEntities([
      PLAYER,
      BELONGABLE,
      DROPPABLE,
      RENDERABLE,
      POSITION,
      LAYER,
      LIGHT,
      VIEWABLE,
      SPAWNABLE,
      EQUIPPABLE,
      SEQUENCABLE,
      STATS,
    ])) {
      if (isDead(world, entity) && isDecayed(world, entity)) {
        // disable any focus
        setNeedle(world);
        setHighlight(world);

        // close popups
        if (entity[PLAYER].popup) {
          closePopup(world, entity, world.assertById(entity[PLAYER].popup));
        }

        const defaultVision =
          entity[LIGHT].visibility === defaultLight.visibility &&
          entity[LIGHT].brightness === defaultLight.brightness;

        // create tombstone and play RIP animation
        const tombstonePosition = getBurning(world, entity[POSITION])
          ? findAdjacentDroppable(world, entity[POSITION])
          : copy(entity[POSITION]);
        const tombstoneEntity = entities.createTombstone(world, {
          [FOG]: { visibility: "visible", type: "object" },
          [LAYER]: { structure: entity[LAYER].structure },
          [POSITION]: copy(tombstonePosition),
          [RENDERABLE]: { generation: 0 },
          [REVIVABLE]: { available: false },
          [SEQUENCABLE]: { states: {} },
          [SPRITE]: tombstone1,
          [SWIMMABLE]: { swimming: false },
          [TOOLTIP]: { dialogs: [], nextDialog: -1, persistent: false },
        });
        createSequence<"perish", PerishSequence>(
          world,
          tombstoneEntity,
          "perish",
          "tragicDeath",
          { fast: defaultVision }
        );
        registerEntity(world, tombstoneEntity);

        // create halo and reduce vision radius
        const frameId = world.getEntityId(
          entities.createFrame(world, {
            [REFERENCE]: {
              tick: getHasteInterval(world, -1),
              delta: 0,
              suspended: true,
              suspensionCounter: -1,
            },
            [RENDERABLE]: { generation: 0 },
          })
        );

        const haloEntity = entities.createHalo(world, {
          [ACTIONABLE]: {
            spellTriggered: false,
            skillTriggered: false,
            interactTriggered: false,
            toolEquipped: false,
          },
          [BELONGABLE]: { faction: entity[BELONGABLE].faction },
          [BUMPABLE]: { generation: 0 },
          [EQUIPPABLE]: {},
          [INVENTORY]: { items: [] },
          [LAYER]: { structure: entity[LAYER].structure },
          [LIGHT]: { ...entity[SPAWNABLE].light },
          [MOVABLE]: {
            orientations: [],
            reference: frameId,
            spring: {
              mass: 5,
              friction: 100,
              tension: 200,
            },
            lastInteraction: 0,
            flying: false,
            swimming: false,
          },
          [PLAYER]: {
            ghost: true,
            receivedStats: { ...emptyReceivedStats },
            defeatedUnits: entity[PLAYER].defeatedUnits,
            quickItems: entity[PLAYER].quickItems,
            chatHistory: entity[PLAYER].chatHistory,
          },
          [POSITION]: copy(tombstonePosition),
          [RENDERABLE]: { generation: 0 },
          [SEQUENCABLE]: {
            states: {},
          },
          [SOUL]: {
            stats: {
              level: entity[STATS].level,
              maxHp: entity[STATS].maxHp,
              maxMp: entity[STATS].maxMp,
              maxXp: entity[STATS].maxXp,
            },
            ready: false,
            tombstoneId: world.getEntityId(tombstoneEntity),
          },
          [SPAWNABLE]: {
            classKey: entity[SPAWNABLE].classKey,
            hairColor: entity[SPAWNABLE].hairColor,
            position: copy(entity[SPAWNABLE].position),
            light: { ...entity[SPAWNABLE].light },
            viewable: { ...entity[VIEWABLE] },
            compassId: entity[SPAWNABLE].compassId,
            quest: entity[SEQUENCABLE].states.quest,
          },
          [SPRITE]: none,
          [VIEWABLE]: {
            active: entity[VIEWABLE].active,
            priority: 10,
            spring: {
              mass: 1,
              friction: 30,
              tension: 200,
            },
          },
        });
        createSequence<"vision", VisionSequence>(
          world,
          haloEntity,
          "vision",
          "changeRadius",
          {
            light: { visibility: 1.5, brightness: 1.5, darkness: 0 },
            fast: defaultVision,
          }
        );
        registerEntity(world, haloEntity);
      }
    }

    // grant souls a new life
    for (const entity of world.getEntities([
      BELONGABLE,
      SEQUENCABLE,
      RENDERABLE,
      SOUL,
      LIGHT,
      POSITION,
      VIEWABLE,
      SPAWNABLE,
      PLAYER,
    ])) {
      if (!isSoulReady(world, entity)) continue;

      // spawn new hero
      const heroEntity = createHero(world, entity);

      const heroId = world.getEntityId(heroEntity);
      const compassEntity = world.getEntityByIdAndComponents(
        entity[SPAWNABLE].compassId,
        [ITEM, TRACKABLE]
      );
      const entityId = world.getEntityId(entity);

      if (compassEntity && compassEntity[ITEM].carrier === entityId) {
        const compassId = world.getEntityId(compassEntity);

        // transfer compass to player
        removeFromInventory(world, entity, compassEntity);
        compassEntity[ITEM].carrier = heroId;
        heroEntity[INVENTORY].items.push(compassId);
        heroEntity[EQUIPPABLE].compass = compassId;

        // set needle to spawn
        const spawnEntity = getIdentifier(world, "spawn");
        if (spawnEntity) {
          setNeedle(world, spawnEntity);
        }
      } else if (compassEntity) {
        // only update needle
        compassEntity[TRACKABLE].target = heroId;
      }

      // set waypoint quest to tombstone
      const tombstoneEntity = world.getEntityById(entity[SOUL].tombstoneId);
      if (tombstoneEntity) {
        questSequence(world, heroEntity, "tombstoneQuest", {}, tombstoneEntity);
      }

      registerEntity(world, heroEntity);

      // dispose soul
      entity[SOUL].ready = false;
      disposeEntity(world, entity);
    }
  };

  return { onUpdate };
}
